{(page==='movieSources'||page==='seriesSources')&&<><header><div><h1>{page==='movieSources'?t('Movie sources'):t('Series sources')}</h1><p>{page==='movieSources'?t('The extensions used to find and play movies.'):t('The extensions used to find and play series.')}</p></div></header><section className={'panel anime-status '+(animeEngine?.online?'engine-online':animeEngine?'engine-offline':'')}><div className="engine-row"><div><h2>{t('Video engine')}</h2><p>{animeEngine==null?t('Not checked yet'):animeEngine.online?'✓ '+t('Engine running'):'✕ '+t('Engine offline')+' — '+animeEngine.baseUrl}</p></div><button onClick={async()=>setAnimeEngine(await window.novelReader.miwayomiStatus())}>{t('Check engine')}</button></div></section><section className="panel"><div className="engine-row"><div><h2>{t('Recommended source pack')}</h2><p>{t('Installs a selection of movie and series extensions in one click. Your anime sources are not changed.')}</p></div><button className="primary" disabled={animeSourceLoading} onClick={installMovieSeriesPack}>{animeSourceLoading?t('Installing…'):t('Install the pack')}</button></div>{animeNotice&&animeNotice.scope==='sources'&&<div className={'anime-toast '+(animeNotice.ok?'ok':'error')}><NoticeText text={animeNotice.text}/><button onClick={()=>setAnimeNotice(null)}>×</button></div>}</section></>}
{page==='animeSources'&&<><header><div><h1>{t('Video sources')}</h1><p>{t('Aniyomi-compatible extension repositories, shared by Anime, Series and Movies.')}</p></div></header><section className={'panel anime-status '+(animeEngine?.online?'engine-online':animeEngine?'engine-offline':'')}><div className="engine-row"><div><h2>{t('Video engine')}</h2><p>{animeEngine==null?t('Not checked yet'):animeEngine.online?'✓ '+t('Engine running'):'✕ '+t('Engine offline')+' — '+animeEngine.baseUrl}</p></div><button onClick={async()=>setAnimeEngine(await window.novelReader.miwayomiStatus())}>{t('Check engine')}</button></div></section><VideoSourceHealth/><CloudflarePanel/><section className="panel"><div className="engine-row"><div><h2>{t('Extension repositories')}</h2><p>{t('Enabled repositories are merged into one source catalogue.')}</p></div><button className="primary" disabled={animeSourceLoading} onClick={async()=>{setAnimeSourceLoading(true);setAnimeNotice(null);try{const repos=animeRepos.filter((x:any)=>x.enabled&&x.url);if(!repos.length)throw Error(t('Enable at least one repository'));await window.novelReader.miwayomiFetch('/api/v1/extensions/repos','POST',{repos:repos.map((x:any)=>x.url)});const settled=await Promise.allSettled(repos.map(async(repo:any)=>{const r=await fetch(repo.url);if(!r.ok)throw Error(repo.name+' HTTP '+r.status);const data=await r.json();const list=Array.isArray(data)?data:(data.extensions||data.plugins||data.items||[]);return list.map((x:any)=>({...x,repoUrl:repo.url,repoName:repo.name}))}));const blocked=/hentai|jav|missav|xvideos|xnxx|myreadingmanga|debrid|nyaa|jable/i;const merged=settled.flatMap((r:any)=>r.status==='fulfilled'?r.value:[]).filter((x:any)=>!blocked.test(String(x.name||x.pkg||'')));const seen=new Set<string>();setAnimeSources(merged.filter((x:any)=>{const k=String(x.pkg||x.package||x.packageName||x.name||'').toLowerCase();if(!k||seen.has(k))return false;seen.add(k);return true}));const failed=settled.filter((r:any)=>r.status==='rejected').length;setAnimeNotice({ok:true,scope:'sources',text:t('Loaded {n} extensions from {repos} repositories.',{n:merged.length,repos:repos.length})+(failed?' '+plural(failed,'{n} repository failed.','{n} repositories failed.'):'')})}catch(e:any){setAnimeNotice({ok:false,scope:'sources',text:e.message})}finally{setAnimeSourceLoading(false)}}}>{animeSourceLoading?t('Loading…'):t('Load all sources')}</button></div><div className="repo-list">{animeRepos.map((r:any,i:number)=><div className="repo-row" key={r.url+i}><label><input type="checkbox" checked={!!r.enabled} onChange={e=>{const next=animeRepos.map((x:any,j:number)=>j===i?{...x,enabled:e.target.checked}:x);setAnimeRepos(next);localStorage.setItem('animeRepos',JSON.stringify(next))}}/><span><b>{r.name}</b><small>{r.url}</small></span></label><button className="removebtn" onClick={()=>{const next=animeRepos.filter((_:any,j:number)=>j!==i);setAnimeRepos(next);localStorage.setItem('animeRepos',JSON.stringify(next))}}>{t('Remove')}</button></div>)}</div><div className="repo-add"><input className="repo-input" placeholder={t('Repository URL (index.min.json)')} value={animeRepoUrl} onChange={e=>setAnimeRepoUrl(e.target.value)}/><button onClick={()=>{const url=animeRepoUrl.trim();if(!url||animeRepos.some((r:any)=>r.url===url))return;const next=[...animeRepos,{name:t('Custom repository'),url,enabled:true}];setAnimeRepos(next);localStorage.setItem('animeRepos',JSON.stringify(next))}}>{t('Add repository')}</button></div>{animeSources.length>0&&<><div className="source-catalog-head"><p>{plural(animeSources.length,'{n} compatible extension','{n} compatible extensions')}</p><input className="repo-input" placeholder={t('Filter sources…')} value={animeCatalogFilter} onChange={e=>setAnimeCatalogFilter(e.target.value)}/></div><div className="anime-source-list">{animeSources.filter((x:any)=>{const q=animeCatalogFilter.toLowerCase();return !q||String(x.name||x.pkg||'').toLowerCase().includes(q)||String(x.lang||'').toLowerCase().includes(q)||String(x.repoName||'').toLowerCase().includes(q)}).slice(0,160).map((x:any,i:number)=><button className="anime-source-chip" key={(x.pkg||x.name||'source')+i} onClick={()=>installAnimeSource(x)} title={t('Repository: {name}',{name:x.repoName||t('Custom repository')})}>{x.name||x.pkg}{x.lang?' · '+x.lang:''}<small>{x.repoName?' · '+x.repoName:''}</small></button>)}</div></>}{animeNotice&&animeNotice.scope==='sources'&&<div className={'anime-toast '+(animeNotice.ok?'ok':'error')}><NoticeText text={animeNotice.text}/><button onClick={()=>setAnimeNotice(null)}>×</button></div>}</section></>}
